<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { Layers3, LayoutGrid, Users, ArrowUpRight, Plus, X, Download, Upload, Share2, Check, RotateCcw, Search, ChevronRight, Sparkles, GripVertical, Trash2, LoaderCircle, ShieldCheck } from 'lucide-vue-next';
import { seasons,loadDatabase,avatar,image,ranks,rankColors } from './data';
import {resolveMembers,buildBondCatalog,previewBonds,moveRoster,normalizeRoster} from '../shared/planner';
import {validatePlan} from '../shared/plan';
import type {Database,Piece,Plan,PlazaItem,Operator} from '../shared/types';
const page=ref(location.hash==='#plaza'?'plaza':'editor');
const season=ref(seasons[0].key),db=ref<Database|null>(null),loading=ref(false),error=ref(''),toast=ref('');
let messageTimer:ReturnType<typeof setTimeout>;
function notify(text:string){toast.value=text;clearTimeout(messageTimer);messageTimer=setTimeout(()=>toast.value='',4500);}
const draftKey='protocol-database-drafts-v1';
function readDrafts():Record<string,{members:Piece[];personnel:boolean}>{try{return JSON.parse(localStorage.getItem(draftKey)||'{}')}catch{return {}}}
const saved=readDrafts(), pieces=ref<Piece[]>([]),personnel=ref(false),view=ref('terrain'),rank=ref(''),bond=ref('');
let request=0;
watch(season,async key=>{const seq=++request; loading.value=true;error.value='';db.value=null;pieces.value=saved[key]?.members||[];personnel.value=saved[key]?.personnel||false;rank.value='';bond.value='';try{const result=await loadDatabase(key);if(seq===request)db.value=result;}catch(e){if(seq===request)error.value=(e as Error).message;}finally{if(seq===request)loading.value=false;}},{immediate:true});
watch([pieces,personnel],()=>{saved[season.value]={members:pieces.value,personnel:personnel.value};try{localStorage.setItem(draftKey,JSON.stringify(saved))}catch{notify('本地草稿保存失败，请导出备份')}},{deep:true});
watch(page,p=>{location.hash=p==='plaza'?'plaza':'editor';if(p==='plaza')refreshPlaza();});
window.addEventListener('hashchange',()=>{page.value=location.hash==='#plaza'?'plaza':'editor';});
if(page.value==='plaza')setTimeout(()=>refreshPlaza(),0);
const capacity=computed(()=>personnel.value?9:8);
const members=computed(()=>db.value?resolveMembers(pieces.value,db.value.opList):[]);
const field=computed(()=>members.value.filter(m=>m.zone==='board')),reserve=computed(()=>members.value.filter(m=>m.zone==='reserve'));
const catalog=computed(()=>db.value?buildBondCatalog(db.value):[]);
const bonds=computed(()=>previewBonds(catalog.value,members.value).filter(b=>b.count>0));
const operators=computed(()=>Object.values(db.value?.opList||{}).filter(op=>(!rank.value||op.chess[0].rank===Number(rank.value))&&(!bond.value||op.chess.some(c=>c.bonds.some(b=>b.id===bond.value)))).sort((a,b)=>a.chess[0].rank-b.chess[0].rank));
const board=computed(()=>Array.from({length:36},(_,i)=>field.value.find(m=>m.cell===i)));
const activeCount=computed(()=>bonds.value.filter(b=>b.active).length);
const selectedBond=ref<string|null>(null);const detail=computed(()=>catalog.value.find(b=>b.id===selectedBond.value));
const related=computed(()=>Object.values(db.value?.opList||{}).filter(op=>detail.value?.raw.activeConditionTemplate==='count_threshold_upward_golden'||op.chess.some(c=>c.bonds.some(b=>b.id===selectedBond.value))));
function add(op:Operator,zone:'board'|'reserve'='board',cell:number|null=null){if(!op)return;if(zone==='board'&&field.value.length>=capacity.value)return notify('棋盘已满，请先移出成员');if(zone==='reserve'&&reserve.value.length>=10)return notify('整备区已满');if(cell!==null&&board.value[cell])return notify('请选择空格');pieces.value=[...pieces.value,{id:op.id,uid:crypto.randomUUID(),form:0,zone,cell:zone==='reserve'?null:cell??board.value.findIndex(m=>!m)}];}
function move(uid:string,zone:'board'|'reserve',cell:number|null=null){try{pieces.value=moveRoster(members.value,uid,zone,capacity.value,cell)}catch(e){notify((e as Error).message)}}
function remove(uid:string){pieces.value=pieces.value.filter(m=>m.uid!==uid)}
function toggle(uid:string){pieces.value=pieces.value.map(m=>m.uid===uid?{...m,form:m.form===1?0:1}:m)}
function switchPersonnel(){if(personnel.value&&field.value.length>8)return notify('请先将棋盘人数减少至 8 人');personnel.value=!personnel.value;}
const drag=ref<{source:'pool'|'piece';id:string}|null>(null),hover=ref<number|null>(null),placing=ref<string|null>(null);
function startDrag(e:DragEvent,id:string,source:'pool'|'piece'){drag.value={id,source};e.dataTransfer!.setData('application/x-protocol-piece',JSON.stringify(drag.value));e.dataTransfer!.effectAllowed='move';}
function endDrag(){drag.value=null;hover.value=null;}
function over(e:DragEvent,cell:number|null=null){if(drag.value){e.preventDefault();hover.value=cell;}}
function drop(e:DragEvent,zone:'board'|'reserve'|'delete',cell:number|null=null){e.preventDefault();e.stopPropagation();if(!drag.value||e.dataTransfer?.getData('application/x-protocol-piece')!==JSON.stringify(drag.value))return;const {id,source}=drag.value;if(zone==='delete'){if(source==='piece')remove(id)}else if(source==='pool'){add(db.value!.opList[id],zone,cell)}else move(id,zone,cell);endDrag();}
function clickCell(cell:number){if(placing.value){move(placing.value,'board',cell);placing.value=null;}else if(board.value[cell])placing.value=board.value[cell]!.uid;}
const modal=ref<'share'|'import'|'clear'|null>(null),title=ref(''),description=ref(''),importText=ref(''),busy=ref(false);
function plan():Plan{return {version:4,season:season.value,personnel:personnel.value,members:pieces.value}}
function exportPlan(){const url=URL.createObjectURL(new Blob([JSON.stringify(plan(),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`protocol-${season.value}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function applyPlan(input:unknown){const p=validatePlan(input);if(p.season!==season.value)throw new Error('请先切换到阵容对应活动期');if(!db.value)throw new Error('请等待游戏数据加载');for(const m of p.members)if(!db.value.opList[m.id]?.chess[m.form])throw new Error('阵容包含当前活动期不可用干员');pieces.value=p.members;personnel.value=p.personnel;}
function importPlan(){try{applyPlan(JSON.parse(importText.value));modal.value=null;notify('阵容导入成功')}catch(e){notify((e as Error).message)}}
async function fileImport(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(file){if(file.size>100000)return notify('文件过大');importText.value=await file.text();}}
async function api<T>(path:string,options:RequestInit={}):Promise<T>{const response=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json',...options.headers}});const body=response.status===204?null:await response.json();if(!response.ok)throw new Error(body?.error||'请求失败');return body;}
const entries=ref<PlazaItem[]>([]),plazaLoading=ref(false),plazaError=ref(''),search=ref(''),selectedEntry=ref<PlazaItem|null>(null),confirmEntry=ref<PlazaItem|null>(null);
const visibleEntries=computed(()=>entries.value.filter(e=>e.title.toLowerCase().includes(search.value.toLowerCase())));
async function refreshPlaza(){plazaLoading.value=true;plazaError.value='';try{entries.value=(await api<{items:PlazaItem[]}>('/squads?season=regulation_seq1')).items}catch(e){plazaError.value=(e as Error).message}finally{plazaLoading.value=false}}
async function publish(){if(!title.value.trim())return;busy.value=true;try{await api('/squads',{method:'POST',body:JSON.stringify({title:title.value,description:description.value,plan:plan()})});modal.value=null;title.value='';description.value='';page.value='plaza';notify('已发布到阵容广场')}catch(e){notify((e as Error).message)}finally{busy.value=false}}
async function deleteEntry(entry:PlazaItem){if(!confirm('确定删除自己发布的这个阵容？'))return;try{await api('/squads/'+entry.id,{method:'DELETE'});selectedEntry.value=null;refreshPlaza()}catch(e){notify((e as Error).message)}}
function loadEntry(){try{applyPlan(confirmEntry.value!.plan);confirmEntry.value=null;selectedEntry.value=null;page.value='editor';notify('已载入编辑器')}catch(e){notify((e as Error).message)}}
function seasonLabel(key:string){return seasons.find(s=>s.key===key)?.name||key}
</script>

<template>
  <div class="app-shell">
    <header class="site-header"><a class="brand" href="#editor" @click.prevent="page='editor'"><span class="brand-icon"><Layers3 :size="22"/></span><span>协议数据库</span></a><nav><button :class="{active:page==='editor'}" @click="page='editor'"><LayoutGrid :size="16"/>阵容编辑器</button><button :class="{active:page==='plaza'}" @click="page='plaza'"><Users :size="16"/>阵容广场</button></nav></header>
    <main>
      <section class="page-intro"><div><h1>{{page==='editor'?'让每一份灵感，成为阵容。':'好阵容，值得被看见。'}}</h1></div><div class="intro-mark"><Layers3 :size="82" :stroke-width="1"/></div></section>
      <div class="toolbar"><div class="season-select"><span>活动期</span><strong>规程 · 序列 I</strong></div><div v-if="page==='editor'" class="actions"><button @click="modal='import'"><Upload :size="15"/>导入</button><button @click="exportPlan"><Download :size="15"/>导出</button><button class="primary" :disabled="!field.length" @click="modal='share'"><Share2 :size="15"/>分享到广场</button></div><button v-else class="primary" @click="page='editor'"><Plus :size="16"/>创建阵容</button></div>
      <div v-if="loading" class="status"><LoaderCircle class="spin"/>正在同步活动期数据…</div><div v-if="error" class="error-box">{{error}} <button @click="loadDatabase(season).then(v=>{db=v;error='' }).catch(e=>error=e.message)">重试</button></div>
      <div v-if="page==='editor'&&db&&!loading" class="editor-layout">
        <aside class="panel pool" :class="{'delete-target':drag?.source==='piece'}" @dragover="over($event)" @drop="drop($event,'delete')"><div class="panel-title"><span><Users :size="17"/>干员选择</span><b>{{operators.length}}</b></div><div class="filters"><select v-model="rank"><option value="">全部等阶</option><option v-for="(r,i) in ranks" :value="i+1">{{r}} 阶</option></select><select v-model="bond"><option value="">全部盟约</option><optgroup v-for="type in ['SEASON','REGULAR']" :label="type==='SEASON'?'核心盟约':'附加盟约'"><option v-for="b in catalog.filter(b=>b.type===type)" :value="b.id">{{b.name}}</option></optgroup></select></div><div v-if="drag?.source==='piece'" class="delete-hint"><Trash2 :size="16"/>拖到这里移除棋子</div><div class="pool-grid"><button v-for="op in operators" :key="op.id" class="operator" draggable="true" @dragstart="startDrag($event,op.id,'pool')" @dragend="endDrag" @click="add(op)"><span class="portrait" :style="{'--rank-color':rankColors[op.chess[0].rank-1]}"><img :src="avatar(op.id)" :alt="op.name" draggable="false"/><i>{{ranks[op.chess[0].rank-1]}}</i><img class="profession" :src="image(`图标_职业_${op.profession}.png`)" :alt="op.profession"/></span><strong>{{op.name}}</strong><small>{{op.chess[0].bonds.map(b=>b.name).join(' · ')}}</small></button></div></aside>
        <section class="preview-column"><div class="panel"><div class="panel-title"><span><LayoutGrid :size="17"/>阵容预览 <b>{{field.length}} / {{capacity}}</b></span><button class="document" :class="{checked:personnel}" @click="switchPersonnel"><span class="checkbox"><Check v-if="personnel" :size="11"/></span>人事部文档</button></div><div class="preview-controls"><div class="segmented"><button :class="{selected:view==='terrain'}" @click="view='terrain'">地形预览</button><button :class="{selected:view==='normal'}" @click="view='normal'">常规预览</button></div><button class="text-button" @click="modal='clear'"><RotateCcw :size="13"/>清空</button></div>
        <template v-if="view==='terrain'"><div class="board-wrap"><div class="map-caption"><span>部署区域</span><span>9 × 4</span></div><div class="board"><button v-for="(member,cell) in board" :key="cell" class="cell" :class="{occupied:member,hover:hover===cell,placing:member?.uid===placing}" :draggable="!!member" @dragstart="member&&startDrag($event,member.uid,'piece')" @dragend="endDrag" @dragover="over($event,cell)" @drop="drop($event,'board',cell)" @click="clickCell(cell)"><template v-if="member"><span class="portrait map-portrait" :style="{'--rank-color':rankColors[member.chess.rank-1]}"><img :src="avatar(member.id)" :alt="member.op.name" draggable="false"/><i>{{ranks[member.chess.rank-1]}}</i></span><span class="map-name">{{member.op.name}}</span><b v-if="member.form" class="elite-star">★</b></template><Plus v-else :size="13"/></button></div><div v-if="placing" class="inline-tools"><span>已选择 {{members.find(m=>m.uid===placing)?.op.name}}</span><button @click="toggle(placing)">普通 / 精锐</button><button @click="move(placing,'reserve');placing=null">整备</button><button @click="remove(placing);placing=null">移除</button></div></div></template>
        <div v-else class="normal-board" @dragover="over($event)" @drop="drop($event,'board')"><div class="piece-grid"><article v-for="m in field" :key="m.uid" class="piece" draggable="true" @dragstart="startDrag($event,m.uid,'piece')" @dragend="endDrag"><button class="remove" @click="remove(m.uid)"><X :size="12"/></button><span class="portrait" :style="{'--rank-color':rankColors[m.chess.rank-1]}"><img :src="avatar(m.id)"/><i>{{ranks[m.chess.rank-1]}}</i></span><strong>{{m.op.name}}</strong><small>{{m.chess.bonds.map(b=>b.name).join(' · ')}}</small><button @click="toggle(m.uid)" :class="{gold:m.form}">{{m.form?'精锐':'普通'}}</button><button @click="move(m.uid,'reserve')">移入整备</button></article><div class="piece-placeholder" v-for="i in Math.max(0,capacity-field.length)"><Plus :size="18"/><small>等待部署</small></div></div></div>
        <div class="reserve-area" @dragover="over($event)" @drop="drop($event,'reserve')"><div class="section-label"><h3>整备区 <b>{{reserve.length}} / 10</b></h3></div><div class="reserve-grid"><article v-for="m in reserve" :key="m.uid" class="reserve-piece" draggable="true" @dragstart="startDrag($event,m.uid,'piece')" @dragend="endDrag"><button class="remove" @click="remove(m.uid)"><X :size="11"/></button><span class="portrait" :style="{'--rank-color':rankColors[m.chess.rank-1]}"><img :src="avatar(m.id)"/><i>{{ranks[m.chess.rank-1]}}</i></span><small>{{m.op.name}}</small><button @click="toggle(m.uid)">{{m.form?'精锐':'普通'}}</button><button @click="move(m.uid,'board')">上场</button></article><div class="reserve-empty" v-for="i in Math.max(0,10-reserve.length)"><Plus :size="14"/></div></div></div></div></section>
        <aside class="panel bond-panel"><div class="panel-title"><span><Sparkles :size="17"/>羁绊预览</span><b>{{activeCount}} 已激活</b></div><div v-if="!bonds.length" class="empty-small">选择干员后，羁绊会出现在这里。</div><template v-for="active in [true,false]"><div class="bond-section" v-if="bonds.some(b=>b.active===active)"><h3><i :class="{on:active}"/>{{active?'已激活':'未激活'}}</h3><button v-for="b in bonds.filter(b=>b.active===active)" :key="b.id" class="bond" :class="{on:active}" @click="selectedBond=b.id"><span class="bond-icon"><img :src="image(`卫戍协议：盟约_icon_${b.id}.png`)"/></span><span><strong>{{b.name}}</strong><small>{{b.type==='SEASON'?'核心盟约':'附加盟约'}}{{b.bonus?' · 调和 +1':''}}</small></span><b>{{b.effectiveCount}}<em>/{{b.target}}</em></b><ChevronRight :size="13"/></button></div></template></aside>
      </div>
      <section v-if="page==='plaza'" class="plaza-section"><div class="plaza-heading"><div><h2>灵感集合 </h2><p>数据库持久保存，和其他玩家交换搭配思路。</p></div><label class="search"><Search :size="16"/><input v-model="search" placeholder="搜索阵容名称"/></label></div><div v-if="plazaLoading" class="status"><LoaderCircle class="spin"/>加载阵容中…</div><div v-if="plazaError" class="error-box">{{plazaError}}<button @click="refreshPlaza">重试</button></div><div v-if="!plazaLoading&&!plazaError&&!visibleEntries.length" class="empty-plaza"><Users :size="42"/><h3>第一个灵感，留给你。</h3><p>在编辑器完成阵容后，分享给广场吧。</p><button class="primary" @click="page='editor'">开始搭配 <ArrowUpRight :size="15"/></button></div><div class="plaza-grid"><article v-for="entry in visibleEntries" :key="entry.id" class="plaza-card"><div class="card-top"><span class="tag">{{seasonLabel(entry.season)}}</span><span v-if="entry.owned" class="mine">我的发布</span></div><h3>{{entry.title}}</h3><p>{{entry.description||'让搭配自己说话。'}}</p><div class="lineup-faces"><img v-for="m in entry.plan.members.filter(m=>m.zone==='board')" :key="m.uid" :src="avatar(m.id)"/></div><div class="card-bottom"><span>{{new Date(entry.createdAt).toLocaleDateString('zh-CN')}}</span><button @click="selectedEntry=entry">查看阵容 <ArrowUpRight :size="15"/></button></div></article></div></section>
    </main><footer><span class="footer-brand"><Layers3 :size="16"/> Protocol Database</span><span>非官方玩家工具 · 游戏资料及图片版权归原权利人所有</span><a href="https://prts.wiki" target="_blank" rel="noreferrer">数据与素材 · PRTS <ArrowUpRight :size="12"/></a></footer>
    <div v-if="toast" class="toast" role="status">{{toast}}</div>
    <div v-if="modal" class="modal-backdrop" @click.self="modal=null"><section class="modal"><button class="modal-close" @click="modal=null"><X :size="20"/></button><template v-if="modal==='share'"><h2>把灵感，分享出去。</h2><p>发布到当前服务的阵容广场，其他访问者也可以看到。</p><label>阵容名称<input v-model="title" maxlength="60" placeholder="给这个阵容起个名字"/></label><label>搭配说明<textarea v-model="description" maxlength="500" rows="4" placeholder="聊聊核心思路、站位或适用场景…"/></label><small>当前浏览器通过匿名身份管理自己发布的阵容，请勿清除站点 Cookie。</small><button class="primary full" :disabled="busy||!title.trim()" @click="publish">{{busy?'发布中…':'发布到广场'}}<ArrowUpRight :size="16"/></button></template><template v-if="modal==='import'"><h2>导入阵容</h2><p>接受新版及旧编辑器版本 4 文件，导入将覆盖本期草稿。</p><input type="file" accept=".json" @change="fileImport"/><textarea v-model="importText" rows="9" placeholder="粘贴阵容 JSON"/><button class="primary full" @click="importPlan">确认导入</button></template><template v-if="modal==='clear'"><h2>重新开始？</h2><p>清空当前活动期的棋盘和整备区，无法撤销。</p><button class="danger full" @click="pieces=[];placing=null;modal=null">确认清空</button></template></section></div>
    <div v-if="detail" class="modal-backdrop" @click.self="selectedBond=null"><section class="modal"><button class="modal-close" @click="selectedBond=null"><X :size="20"/></button><h2>{{detail.name}}</h2><div class="thresholds"><span v-for="n in detail.thresholds">{{n}} 人</span></div><p class="effect">{{detail.description}}</p><h4>关联干员</h4><div class="related"><div v-for="op in related" :class="{chosen:members.some(m=>m.id===op.id)}"><img :src="avatar(op.id)"/><small>{{op.name}}</small></div></div></section></div>
    <div v-if="selectedEntry" class="modal-backdrop" @click.self="selectedEntry=null"><section class="modal"><button class="modal-close" @click="selectedEntry=null"><X :size="20"/></button><span class="tag">{{seasonLabel(selectedEntry.season)}}</span><h2>{{selectedEntry.title}}</h2><p class="effect">{{selectedEntry.description}}</p><div class="entry-pieces"><div v-for="m in selectedEntry.plan.members" :key="m.uid"><img :src="avatar(m.id)"/><span>{{db?.opList[m.id]?.name||m.id}}<small>{{m.form?'精锐':'普通'}} · {{m.zone==='board'?'棋盘':'整备'}}</small></span></div></div><p v-if="selectedEntry.season!==season">请先在顶部切换至此阵容活动期。</p><button class="primary full" :disabled="selectedEntry.season!==season||!db" @click="confirmEntry=selectedEntry">载入编辑器</button><button v-if="selectedEntry.owned" class="text-button full" @click="deleteEntry(selectedEntry)">删除我的发布</button></section></div>
    <div v-if="confirmEntry" class="modal-backdrop front" @click.self="confirmEntry=null"><section class="modal"><h2>载入这个阵容？</h2><p>将覆盖当前活动期的本地草稿，请先导出需要保留的阵容。</p><button class="primary full" @click="loadEntry">确认覆盖并载入</button><button class="text-button full" @click="confirmEntry=null">取消</button></section></div>
  </div>
</template>
